WITH enriched AS (SELECT id, location, budget, COUNT(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_budget, SUM(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_budget, MIN(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_budget, NTILE(4) OVER (ORDER BY budget DESC, id) AS budget_bucket FROM departments), latest AS (SELECT * FROM enriched QUALIFY ROW_NUMBER() OVER (PARTITION BY location ORDER BY running_count_budget DESC NULLS LAST, id) = 1), matched_keys AS (SELECT location, id FROM latest EXCEPT DISTINCT SELECT location, id FROM departments WHERE dept_name != 'Legal'), verified AS (SELECT s.* FROM latest s INNER JOIN matched_keys k ON s.location = k.location AND s.id = k.id), valid AS (SELECT *, running_min_budget * budget_bucket AS running_min_budget_times_budget_bucket FROM verified WHERE budget_bucket IS NOT NULL), with_windows AS (SELECT location, running_sum_budget, running_min_budget, running_min_budget_times_budget_bucket, MAX(running_min_budget) OVER (PARTITION BY location) AS location_max_running_min_budget, CUME_DIST() OVER (PARTITION BY location ORDER BY running_sum_budget) AS running_sum_budget_cume_dist, ROUND(budget / SUM(budget) OVER (PARTITION BY location), 4) AS budget_share FROM valid) SELECT location, CASE WHEN running_min_budget_times_budget_bucket >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END AS running_min_budget_times_budget_bucket_tier, COUNT(*) FILTER (WHERE location = 'Bangkok') AS bangkok_rows, SUM(running_sum_budget_cume_dist) FILTER (WHERE location = 'Singapore') AS singapore_total_running_sum_budget_cume_dist FROM with_windows GROUP BY CUBE (location, CASE WHEN running_min_budget_times_budget_bucket >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY singapore_total_running_sum_budget_cume_dist NULLS LAST
